1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Single source of truth for an owner's {@code identityKey} — a derived value returned on the
9	 * owner DTO and used for duplicate detection. The key is the lower-case hex SHA-256 (see
10	 * {@link Hashing}) of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}.
11	 *
12	 * <p>The inputs are normalized the same way for every owner so stored owners and the owner being
13	 * created compare consistently: the telephone to its E.164 form (see {@link OwnerTelephones}, so a
14	 * stored value that predates the pipeline still compares correctly), the email trimmed and
15	 * lower-cased (empty when absent), and the last name reduced to its {@link Soundex} code. Hard
16	 * duplicate detection (409) compares this key (see {@link RejectDuplicateIdentity}); the soft
17	 * signal keys on the weaker {@code soundex(lastName)} + {@code postcode} pair (see
18	 * {@link FlagPossibleDuplicate}). The key is exposed by the owner mapper.
19	 *
20	 * <p>Because the telephone is part of the key, two owners sharing a last name and postcode but
21	 * carrying different telephones produce <em>different</em> identity keys — they are a soft match,
22	 * not a hard duplicate.
23	 */
24	public final class OwnerIdentity {
25	
26	    private OwnerIdentity() {
27	    }
28	
29	    /** The owner's duplicate-detection identity key: SHA-256 hex over the normalized inputs. */
30	    public static String identityKey(Owner owner) {
31	        String canonical = normalizedTelephone(owner) + "|" + lowerEmail(owner) + "|" + Soundex.of(owner.getLastName());
32	        return Hashing.sha256Hex(canonical);
33	    }
34	
35	    /**
36	     * The owner's telephone in its normalized E.164 form (see {@link OwnerTelephones#toE164}),
37	     * falling back to the stored raw value (or empty) when it cannot be normalized.
38	     */
39	    static String normalizedTelephone(Owner owner) {
40	        String telephone = OwnerTelephones.toE164(owner.getTelephone());
41	        if (telephone == null) {
42	            telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
43	        }
44	        return telephone;
45	    }
46	
47	    /** The owner's email trimmed and lower-cased, or empty when absent. */
48	    static String lowerEmail(Owner owner) {
49	        String email = owner.getEmail();
50	        return (email == null || email.isBlank()) ? "" : email.trim().toLowerCase(Locale.ROOT);
51	    }
52	}
