1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Objects;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * The identity of a household: the same last name and the same postcode. The last name is
10	 * compared case-insensitively with whitespace trimmed and collapsed; the postcode is compared
11	 * as stored. So e.g. "  Smith " at postcode "2000" is the same household as "smith" at "2000".
12	 *
13	 * <p>Single-sources the "what is a household" definition. The {@code householdId} is derived
14	 * <em>deterministically</em> from this key (see {@link #householdId()}): the first 12 hex
15	 * characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Every owner computes
16	 * the same id for the same household automatically, so two owners share a {@code householdId}
17	 * exactly when they share a last name and postcode — no opt-in and no back-filling required.
18	 */
19	final class HouseholdKey {
20	
21	    private final String lastName;
22	
23	    private final String postcode;
24	
25	    private HouseholdKey(String lastName, String postcode) {
26	        this.lastName = lastName;
27	        this.postcode = postcode;
28	    }
29	
30	    /** The household the given owner belongs to. */
31	    static HouseholdKey of(Owner owner) {
32	        return new HouseholdKey(normalize(owner.getLastName()), owner.getPostcode() == null ? "" : owner.getPostcode());
33	    }
34	
35	    /** Whether {@code owner} belongs to this household. */
36	    boolean matches(Owner owner) {
37	        return equals(of(owner));
38	    }
39	
40	    /** Stable canonical form of the key, suitable for deriving a shared identifier. */
41	    private String canonical() {
42	        return lastName + "|" + postcode;
43	    }
44	
45	    /**
46	     * The deterministic {@code householdId} for this household: the first 12 hex characters of
47	     * SHA-256 over {@link #canonical()}. Owners with the same last name and postcode compute the
48	     * same value, so they share a household automatically.
49	     */
50	    String householdId() {
51	        return Hashing.sha256HexPrefix(canonical(), 6);
52	    }
53	
54	    @Override
55	    public boolean equals(Object o) {
56	        if (this == o) {
57	            return true;
58	        }
59	        if (!(o instanceof HouseholdKey other)) {
60	            return false;
61	        }
62	        return lastName.equals(other.lastName) && postcode.equals(other.postcode);
63	    }
64	
65	    @Override
66	    public int hashCode() {
67	        return Objects.hash(lastName, postcode);
68	    }
69	
70	    @Override
71	    public String toString() {
72	        return canonical();
73	    }
74	
75	    /** Lower-case, trim, and collapse any run of whitespace to a single space. */
76	    private static String normalize(String value) {
77	        if (value == null) {
78	            return "";
79	        }
80	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
81	    }
82	}
