1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Single source of truth for an owner's {@code REGION} code — the geographic segment of
9	 * the owner's {@code memberId} identity ({@code <REGION><FY><HASH8><CHK>}) and, through
10	 * it, the owner's locality.
11	 *
12	 * <p>The region is derived from the postcode first: a 4-digit postcode falling within a
13	 * known region's inclusive range yields that region. When the postcode is absent or in no
14	 * known range, it falls back to the {@link #CITY_REGION} table, returning {@code UNKNOWN}
15	 * when the city is not listed.
16	 */
17	public final class OwnerRegion {
18	
19	    private OwnerRegion() {
20	    }
21	
22	    /** Fixed city-to-region table used as the fallback when the postcode does not resolve a region. */
23	    static final Map<String, String> CITY_REGION = Map.of(
24	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
25	
26	    /** Region-to-inclusive 4-digit postcode range {low, high}. */
27	    static final Map<String, int[]> REGION_POSTCODES = Map.of(
28	            "NSW", new int[] {2000, 2099},
29	            "VIC", new int[] {3000, 3099},
30	            "QLD", new int[] {4000, 4099});
31	
32	    /** Fixed region-to-IANA-timezone table. */
33	    static final Map<String, String> REGION_TIMEZONE = Map.of(
34	            "NSW", "Australia/Sydney",
35	            "VIC", "Australia/Melbourne",
36	            "QLD", "Australia/Brisbane");
37	
38	    /** Whether the region code is one of the known regions (NSW, VIC, QLD). */
39	    public static boolean isKnownRegion(String region) {
40	        return region != null && REGION_POSTCODES.containsKey(region);
41	    }
42	
43	    /** The IANA timezone name for a region code, or {@code null} when the region has no mapping. */
44	    public static String timezoneOfRegion(String region) {
45	        return region == null ? null : REGION_TIMEZONE.get(region);
46	    }
47	
48	    /** The owner's region code, derived from the postcode (city table as fallback). */
49	    public static String regionOf(Owner owner) {
50	        String postcode = owner.getPostcode();
51	        if (postcode != null && postcode.matches("[0-9]{4}")) {
52	            int value = Integer.parseInt(postcode);
53	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
54	                int[] range = entry.getValue();
55	                if (value >= range[0] && value <= range[1]) {
56	                    return entry.getKey();
57	                }
58	            }
59	        }
60	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
61	    }
62	
63	    /** Length of the fixed trailing {@code <FY><HASH8><CHK>} segment of a memberId:
64	     *  2 (fiscal year) + 8 (hash) + 1 (Luhn check digit). */
65	    private static final int MEMBER_ID_SUFFIX_LENGTH = 11;
66	
67	    /**
68	     * Extracts the {@code REGION} segment from a {@code memberId} of the form
69	     * {@code <REGION><FY><HASH8><CHK>} (the layout produced by
70	     * {@link AssignOwnerMemberId}), optionally followed by a {@code -<n>} collision
71	     * suffix. Returns {@code null} when the id is {@code null}; returns the whole id when
72	     * it is too short to carry the fixed trailing segment.
73	     */
74	    public static String regionFromMemberId(String memberId) {
75	        if (memberId == null) {
76	            return null;
77	        }
78	        int dash = memberId.indexOf('-');
79	        String base = dash >= 0 ? memberId.substring(0, dash) : memberId;
80	        return base.length() > MEMBER_ID_SUFFIX_LENGTH
81	                ? base.substring(0, base.length() - MEMBER_ID_SUFFIX_LENGTH) : base;
82	    }
83	}
