1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import java.util.HashSet;
8	import java.util.Set;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	/**
15	 * Assigns the owner's unified {@code memberId} on create, formatted
16	 * {@code <REGION><FY><HASH8><CHK>} where {@code REGION} is the region code derived from
17	 * the postcode (see {@link OwnerRegion}), {@code FY} is the two-digit fiscal year of the
18	 * (business-day-adjusted) registration date (see {@link OwnerFiscalYear}), {@code HASH8}
19	 * is the first 8 upper-case hex characters of SHA-256 over
20	 * ({@code normalizedTelephone + lastName}) and {@code CHK} is a single Luhn check digit
21	 * computed over the digits of {@code <REGION><FY><HASH8>} (e.g. {@code NSW261A2B3C4D7}).
22	 *
23	 * <p>Runs after the telephone has been normalized to E.164 and the registration date has
24	 * been rolled to a business day, so both the hash and the fiscal year are stable over the
25	 * stored values. The base id is fully determined by those inputs; should it collide with
26	 * an existing owner's {@code memberId}, {@code -<n>} is appended with the smallest
27	 * {@code n} of 2 or more that makes it unique.
28	 */
29	public class AssignOwnerMemberId {
30	
31	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
32	        String region = OwnerRegion.regionOf(owner);
33	        String fy = String.format("%02d",
34	                OwnerFiscalYear.fiscalYearOf(owner.getRegistrationDate()) % 100);
35	        String hash8 = sha256Hex8(owner.getTelephone() + owner.getLastName());
36	        String withoutCheck = region + fy + hash8;
37	        String base = withoutCheck + luhnCheckDigit(withoutCheck);
38	
39	        Set<String> existing = new HashSet<>();
40	        for (Owner other : ownerRepository.findAll()) {
41	            if (other.getId() != null && other.getId().equals(owner.getId())) {
42	                continue;
43	            }
44	            String memberId = other.getMemberId();
45	            if (memberId != null) {
46	                existing.add(memberId);
47	            }
48	        }
49	
50	        String memberId = base;
51	        for (int n = 2; existing.contains(memberId); n++) {
52	            memberId = base + "-" + n;
53	        }
54	        owner.setMemberId(memberId);
55	    }
56	
57	    /** First 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code s}. */
58	    private static String sha256Hex8(String s) {
59	        try {
60	            byte[] digest = MessageDigest.getInstance("SHA-256")
61	                    .digest(s.getBytes(StandardCharsets.UTF_8));
62	            StringBuilder sb = new StringBuilder(8);
63	            for (int i = 0; i < 4; i++) { // 4 bytes -> 8 hex characters
64	                sb.append(String.format("%02X", digest[i]));
65	            }
66	            return sb.toString();
67	        }
68	        catch (NoSuchAlgorithmException e) {
69	            throw new IllegalStateException("SHA-256 not available", e);
70	        }
71	    }
72	
73	    /** Single Luhn check digit (0-9) computed over the digits contained in {@code s}. */
74	    private static int luhnCheckDigit(String s) {
75	        int sum = 0;
76	        boolean dbl = true;
77	        for (int i = s.length() - 1; i >= 0; i--) {
78	            char c = s.charAt(i);
79	            if (c < '0' || c > '9') {
80	                continue;
81	            }
82	            int d = c - '0';
83	            if (dbl) {
84	                d *= 2;
85	                if (d > 9) {
86	                    d -= 9;
87	                }
88	            }
89	            sum += d;
90	            dbl = !dbl;
91	        }
92	        return (10 - (sum % 10)) % 10;
93	    }
94	}
