1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Single source of truth for the SHA-256 hex encoding used to derive stable identifiers, so the
9	 * identity key (see {@link OwnerIdentity}) and the household id (see {@link HouseholdKey}) can
10	 * never drift in how they hash. Hashes the UTF-8 bytes of the input and lower-cases the hex.
11	 */
12	final class Hashing {
13	
14	    private Hashing() {
15	    }
16	
17	    /** Full lower-case hex SHA-256 (64 characters) of the UTF-8 bytes of {@code value}. */
18	    static String sha256Hex(String value) {
19	        return encode(digest(value), 32);
20	    }
21	
22	    /** The first {@code bytes} bytes of SHA-256({@code value}) as lower-case hex ({@code 2*bytes} chars). */
23	    static String sha256HexPrefix(String value, int bytes) {
24	        return encode(digest(value), bytes);
25	    }
26	
27	    private static byte[] digest(String value) {
28	        try {
29	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
30	        }
31	        catch (NoSuchAlgorithmException ex) {
32	            throw new IllegalStateException("SHA-256 not available", ex);
33	        }
34	    }
35	
36	    private static String encode(byte[] digest, int bytes) {
37	        StringBuilder sb = new StringBuilder(bytes * 2);
38	        for (int i = 0; i < bytes; i++) {
39	            sb.append(String.format("%02x", digest[i]));
40	        }
41	        return sb.toString();
42	    }
43	}
