1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Single source of truth for an owner's fiscal year. The fiscal year starts on 1 July
8	 * and is named by the calendar year in which it ends, so a date from 1 July 2025 to
9	 * 30 June 2026 falls in fiscal year 2026.
10	 *
11	 * <p>Everything date-derived that is tracked on a fiscal-year basis — the {@code memberId}'s
12	 * {@code FY} segment and the membership-tenure count — reads through here, off the
13	 * (business-day-adjusted) registration date stored on the owner.
14	 */
15	public final class OwnerFiscalYear {
16	
17	    /** The fiscal year begins on the first day of this month. */
18	    private static final Month FISCAL_YEAR_START = Month.JULY;
19	
20	    private OwnerFiscalYear() {
21	    }
22	
23	    /** The fiscal year (the calendar year it ends in) that {@code date} falls in. */
24	    public static int fiscalYearOf(LocalDate date) {
25	        return date.getMonthValue() >= FISCAL_YEAR_START.getValue() ? date.getYear() + 1 : date.getYear();
26	    }
27	
28	    /** The fiscal year of {@code date} formatted {@code FY<YY>} (e.g. {@code FY26}). */
29	    public static String fiscalYearLabel(LocalDate date) {
30	        return String.format("FY%02d", fiscalYearOf(date) % 100);
31	    }
32	
33	    /** Number of whole fiscal years elapsed from {@code from} to {@code to} (0 when in the same fiscal year). */
34	    public static int elapsedFiscalYears(LocalDate from, LocalDate to) {
35	        return fiscalYearOf(to) - fiscalYearOf(from);
36	    }
37	}
