2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns the owner's deterministic {@code householdId}: the first 12 hex characters of SHA-256
8	 * over the household key (normalized last name and postcode — see {@link HouseholdKey}). Every
9	 * owner is assigned one unconditionally, so owners with the same last name and postcode share the
10	 * same id automatically, with no opt-in and no back-filling of other owners.
11	 *
12	 * <p>The {@code sharesHousehold} create-time flag plays no part here; it only tells
13	 * {@link FlagPossibleDuplicate} not to raise a soft-duplicate signal for a declared household
14	 * member. The stored id feeds {@link OwnerIdentity} and the owner DTO; the household-size count
15	 * and the level cap derive the household themselves from {@link HouseholdKey}, so they do not
16	 * depend on this stored value.
17	 */
18	public class AssignHousehold {
19	
20	    public void service(@Val Owner owner) {
21	        owner.setHouseholdId(HouseholdKey.of(owner).householdId());
22	    }
23	}
