1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code householdSize} on create: the number of owners sharing the same
9	 * household once this owner is counted. The household is keyed on the deterministic
10	 * {@code householdId} (normalized last name and postcode — see {@link HouseholdKey}), so a member
11	 * is any other owner that computes the same id.
12	 *
13	 * <p>The new owner is not yet saved, so it is counted by adding one to the existing same-household
14	 * members. A fully-unique owner (no other owner shares its last name and postcode) is therefore a
15	 * household of one.
16	 */
17	public class CountHouseholdMembers {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        HouseholdKey household = HouseholdKey.of(owner);
21	        int existing = (int) ownerRepository.findAll().stream()
22	                .filter(existingOwner -> existingOwner.getId() == null
23	                        || !existingOwner.getId().equals(owner.getId()))
24	                .filter(existingOwner -> !Boolean.TRUE.equals(existingOwner.getDeleted()))
25	                .filter(household::matches)
26	                .count();
27	        owner.setHouseholdSize(existing + 1);
28	    }
29	}
