12	
13	public class AuditOwnerCreated {
14	
15	    private static final Logger audit = LoggerFactory.getLogger("AUDIT");
16	
17	    /** Shared, thread-safe serializer for the structured event. */
18	    private static final ObjectMapper MAPPER = JsonMapper.builder().build();
19	
20	    /** Monotonically increasing sequence across every owner create in this JVM. */
21	    private static final AtomicLong SEQUENCE = new AtomicLong();
22	
23	    public void service(@Val Owner owner) {
24	        audit.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
25	                owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
26	                owner.getMembershipLevel());
27	
28	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQUENCE.incrementAndGet(),
29	                owner.getId(), primaryIdentifier(owner), owner.getMembershipLevel());
30	        audit.info("{}", MAPPER.writeValueAsString(event));
31	    }
32	
33	    /**
34	     * Resolves the owner's current primary identifier — the single point that decides
35	     * what the event's identifier field carries. The primary identifier is the unified
36	     * {@code memberId}.
37	     */
38	    private static String primaryIdentifier(Owner owner) {
39	        return owner.getMemberId();
40	    }
41	}
