15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "initials",
25	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
26	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
29	    @Mapping(target = "bulkSignupWarning",
30	        expression = "java(Boolean.TRUE.equals(owner.getBulkSignupWarning()))")
31	    @Mapping(target = "capacityWarning",
32	        expression = "java(Boolean.TRUE.equals(owner.getCapacityWarning()))")
33	    @Mapping(target = "possibleDuplicate",
34	        expression = "java(Boolean.TRUE.equals(owner.getPossibleDuplicate()))")
35	    @Mapping(target = "riskFlag", expression = "java(riskFlag(owner))")
36	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
37	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
38	    @Mapping(target = "telephoneDisplay",
39	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerTelephones.toDisplay(owner.getTelephone()))")
40	    @Mapping(target = "identityKey",
41	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.identityKey(owner))")
42	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
43	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
44	    OwnerDto toOwnerDto(Owner owner);
45	
46	    /**
47	     * Derives the owner's segment, formatted {@code <TIER>_<AREA>}. TIER is
48	     * {@code PREMIUM} when the membershipLevel is 3 or more, otherwise
49	     * {@code STANDARD}. AREA is {@code METRO} when the owner's locality is a known
50	     * region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
51	     */
52	    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
53	        Integer level = owner.getMembershipLevel();
54	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
55	        boolean metro = org.springframework.samples.petclinic.rest.function.owner.OwnerRegion
56	            .isKnownRegion(locality(owner));
57	        String area = metro ? "METRO" : "REGIONAL";
58	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
59	    }
60	
61	    /**
62	     * Whether the owner should be flagged for risk review. True when any of these hold:
63	     * the owner is a possible duplicate ({@code possibleDuplicate}); the email domain is
64	     * disposable-adjacent (shares a known throwaway provider's base name under a different
65	     * TLD or as a subdomain, see
66	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerEmails});
67	     * or the city is over its soft capacity (the capacity-warning threshold,
68	     * {@code capacityWarning}). False otherwise.
69	     */
70	    default boolean riskFlag(Owner owner) {
71	        boolean possibleDuplicate = Boolean.TRUE.equals(owner.getPossibleDuplicate());
72	        boolean overSoftCapacity = Boolean.TRUE.equals(owner.getCapacityWarning());
73	        boolean disposableAdjacent = org.springframework.samples.petclinic.rest.function.owner.OwnerEmails
74	            .isDisposableAdjacent(org.springframework.samples.petclinic.rest.function.owner.OwnerEmails
75	                .domainOf(owner.getEmail()));
76	        return possibleDuplicate || overSoftCapacity || disposableAdjacent;
77	    }
78	
79	    /**
80	     * The canonical API path to this owner, formatted {@code /api/owners/<id>}. Null
81	     * until the owner has been assigned an id.
82	     */
83	    default String selfLink(Owner owner) {
84	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
85	    }
86	
87	    /**
88	     * Derives the owner's age band from the {@code birthDate} measured against the
89	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to
90	     * 64 inclusive and {@code SENIOR} at 65 or over. Null when no birth date is present.
91	     */
92	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
93	        java.time.LocalDate birthDate = owner.getBirthDate();
94	        if (birthDate == null) {
95	            return null;
96	        }
97	        java.time.LocalDate reference = owner.getRegistrationDate() != null
98	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
99	        int years = java.time.Period.between(birthDate, reference).getYears();
100	        if (years < 18) {
101	            return OwnerDto.AgeBandEnum.MINOR;
102	        }
103	        if (years < 65) {
104	            return OwnerDto.AgeBandEnum.ADULT;
105	        }
106	        return OwnerDto.AgeBandEnum.SENIOR;
107	    }
108	
109	    /**
110	     * Composes the owner's salutation from the optional title and the last name:
111	     * {@code <title> <lastName>} when a title is present (non-null and not blank),
112	     * or just the last name when no title was supplied.
113	     */
114	    default String salutation(Owner owner) {
115	        String title = owner.getTitle();
116	        if (title != null && !title.isBlank()) {
117	            return title + " " + owner.getLastName();
118	        }
119	        return owner.getLastName();
120	    }
121	
122	    /**
123	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email
124	     * address is present (non-null and not blank), otherwise {@code PHONE}.
125	     */
126	    default String contactPreference(Owner owner) {
127	        String email = owner.getEmail();
128	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
129	    }
130	
131	    /**
132	     * Derives the owner's locality (region) from the owner's {@code memberId}
133	     * identity ({@code <REGION><FY><HASH8><CHK>}): the locality is the {@code REGION}
134	     * segment of that identity. When the member id has not been assigned yet, it falls
135	     * back to deriving the region directly (see
136	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion}).
137	     */
138	    default String locality(Owner owner) {
139	        String region = org.springframework.samples.petclinic.rest.function.owner.OwnerRegion
140	            .regionFromMemberId(owner.getMemberId());
141	        return region != null ? region
142	            : org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.regionOf(owner);
143	    }
144	
145	    /**
146	     * Derives the owner's IANA timezone name from the owner's locality/region via the
147	     * pinned region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
148	     * QLD->Australia/Brisbane). Null when the region has no mapped timezone.
149	     */
150	    default String timezone(Owner owner) {
151	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion
152	            .timezoneOfRegion(locality(owner));
153	    }
154	
155	    /**
156	     * Derives the owner's fiscal year, formatted {@code FY<YY>}, from the
157	     * (business-day-adjusted) registration date. The fiscal year starts on 1 July and
158	     * is named by the calendar year it ends in. Null when no registration date is set.
159	     */
160	    default String fiscalYear(Owner owner) {
161	        if (owner.getRegistrationDate() == null) {
162	            return null;
163	        }
164	        return org.springframework.samples.petclinic.rest.function.owner.OwnerFiscalYear
165	            .fiscalYearLabel(owner.getRegistrationDate());
166	    }
