169	
170	    @Mapping(target = "id", ignore = true)
171	    @Mapping(target = "pets", ignore = true)
172	    Owner toOwner(OwnerFieldsDto ownerDto);
173	
174	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
175	
176	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
177	
