1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * American Soundex of a name: a self-contained, reusable name-similarity rule. The code is the
5	 * retained first letter followed by three digits (zero-padded), with vowels and {@code h}/{@code w}
6	 * not coded and adjacent letters sharing a code collapsed. Returns empty for a null or letterless
7	 * value.
8	 *
9	 * <p>Single-sources name-matching for both the identity key's last-name component (see
10	 * {@link OwnerIdentity}) and the soft-duplicate name match (see {@link FlagPossibleDuplicate}), so
11	 * the two can never disagree on when two surnames sound alike.
12	 */
13	final class Soundex {
14	
15	    private Soundex() {
16	    }
17	
18	    /** The American Soundex code of {@code value}. */
19	    static String of(String value) {
20	        if (value == null) {
21	            return "";
22	        }
23	        StringBuilder letters = new StringBuilder();
24	        for (int i = 0; i < value.length(); i++) {
25	            char c = Character.toUpperCase(value.charAt(i));
26	            if (c >= 'A' && c <= 'Z') {
27	                letters.append(c);
28	            }
29	        }
30	        if (letters.length() == 0) {
31	            return "";
32	        }
33	        StringBuilder code = new StringBuilder();
34	        code.append(letters.charAt(0));
35	        char prev = charCode(letters.charAt(0));
36	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
37	            char c = letters.charAt(i);
38	            if (c == 'H' || c == 'W') {
39	                // Transparent: letters separated by H or W are treated as adjacent.
40	                continue;
41	            }
42	            char cc = charCode(c);
43	            if (cc != '0' && cc != prev) {
44	                code.append(cc);
45	            }
46	            prev = cc;
47	        }
48	        while (code.length() < 4) {
49	            code.append('0');
50	        }
51	        return code.toString();
52	    }
53	
54	    /** American Soundex digit for an upper-case letter; {@code '0'} for vowels and h/w. */
55	    private static char charCode(char c) {
56	        switch (c) {
57	            case 'B': case 'F': case 'P': case 'V':
58	                return '1';
59	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
60	                return '2';
61	            case 'D': case 'T':
62	                return '3';
63	            case 'L':
64	                return '4';
65	            case 'M': case 'N':
66	                return '5';
67	            case 'R':
68	                return '6';
69	            default:
70	                return '0';
71	        }
72	    }
73	}
